(7722863, 1271094, 173844, '<td valign="top">Sees more than we do.  Colors blend well, and the centered composition is handily balanced by the background.  Can''t meet this gaze, in all honesty, more that a few seconds.</td>', 'Sees more than we do.  Colors blend well, and the centered composition is handily balanced by the background.  Can''t meet this gaze, in all honesty, more that a few seconds.', '2022-07-06 00:40:51.000000', NULL, 1),
